export interface SpareItem {
  id: string;
  // Hierarchy linkage - matches assetData.ts exactly
  area: string;          // e.g., "COM" or "REC" - matches Area.code
  areaLabel: string;     // e.g., "Comminution / Process" - matches Area.label
  subArea: string;       // e.g., "Feed / Reclaim" - matches SubArea.label
  system: string;        // e.g., "APN01 Apron Feeder" - matches ParentAsset.label
  parentAsset: string;   // Legacy P&ID reference
  assetNumber: string;   // Modern asset number from tree (e.g., APN01-GMR01)
  pidTag: string;
  // Component details
  componentName: string;
  componentType: string;
  sparePartDescription: string;
  oemPartNumber: string;
  manufacturer: string;
  vendor: string;
  assetManufacturer: string;
  assetModel: string;
  // Criticality
  spareCriticality: "High" | "Medium" | "";
  criticalitySource: "Confirmed" | "Assumed" | "";
  reasonCritical: string;
  // Quantities & Procurement
  minQty: string;
  maxQty: string;
  qtyOnHand?: string;
  qtyPerSystem: string;
  unitPrice: string;
  uom: string;
  leadTimeDays?: string;
  // Other fields
  notes: string;
  confidence?: "Low" | "Medium" | "High";
  status: "Provisional" | "Confirmed" | "TBC";
}

